// app/my/page.tsx — Server Component
import { dehydrate, HydrationBoundary, QueryClient } from '@tanstack/react-query'
import { getSession } from '@/lib/auth'
import { getUserQueryOptions } from '@/features/user/api'
import { MyPageClient } from './my-page-client'

export default async function MyPage() {
  const session = await getSession()                    // 토큰 서버에서만 처리
  const queryClient = new QueryClient()                 // 요청마다 새로 생성

  await queryClient.prefetchQuery(
    getUserQueryOptions(session.userId)                 // 유저 데이터 미리 패칭
  )

  return (
    <HydrationBoundary state={dehydrate(queryClient)}>
      <MyPageClient />
    </HydrationBoundary>
  )
}

