// app/my/my-page-client.tsx — Client Component
'use client'
import { useQuery, useMutation } from '@tanstack/react-query'
import { getUserQueryOptions, updateUser } from '@/features/user/api'

export function MyPageClient() {
  const { data: user } = useQuery(getUserQueryOptions())  // 캐시에서 즉시 읽음

  const { mutate } = useMutation({
    mutationFn: updateUser,
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['user'] }),
  })

  return (
    <div>
      <p>{user.name}님의 마이페이지</p>
      <button onClick={() => mutate({ name: '새 이름' })}>수정</button>
    </div>
  )
}

